#!/usr/bin/env node
import {
  CliHelpRequested,
  CliParseError,
  errorText,
  helpText,
  parseArguments,
  programName,
} from "./lib/cli.mjs";
import { nodeConnectivity } from "./lib/connectivity.mjs";
import { pyFloat, toPythonString } from "./lib/format.mjs";
import { Graph } from "./lib/graph.mjs";
import { bfsEdges, dfsEdges, dijkstraPath, dijkstraPathLength } from "./lib/search.mjs";
import { minimumSpanningTree } from "./lib/spanning.mjs";

function printLine(value) {
  process.stdout.write(`${toPythonString(value)}\n`);
}

export function main(argv = process.argv) {
  const prog = programName(argv);
  let args;

  try {
    args = parseArguments(argv.slice(2), prog);
  } catch (error) {
    if (error instanceof CliHelpRequested) {
      process.stdout.write(helpText(prog));
      return 0;
    }

    if (error instanceof CliParseError) {
      process.stderr.write(errorText(prog, error.message));
      return 2;
    }

    throw error;
  }

  const graph = new Graph();
  graph.addWeightedEdgesFrom([
    [args.a, args.b, pyFloat(1)],
    [args.b, args.c, pyFloat(2)],
    [args.c, args.d, pyFloat(3)],
    [args.d, args.e, pyFloat(4)],
    [args.a, args.e, pyFloat(5)],
  ]);

  printLine(graph.numberOfEdges());
  printLine(graph.getEdgeWeight(args.a, args.b));

  const mst = minimumSpanningTree(graph);
  printLine(mst.numberOfEdges());
  printLine(mst.hasEdge(args.a, args.b));
  printLine(dijkstraPathLength(graph, args.a, args.e));
  printLine(dijkstraPath(graph, args.a, args.e));
  printLine(bfsEdges(graph, args.a));
  printLine(dfsEdges(graph, args.a));
  printLine(nodeConnectivity(graph));
  return 0;
}

const exitCode = main(process.argv);
if (exitCode !== 0) {
  process.exit(exitCode);
}

