}

function isPythonIntLiteral(raw) {
  return /^[+-]?\d(?:_?\d)*$/.test(raw);
}

function parsePythonInt(option, raw) {
  if (!isPythonIntLiteral(raw)) {
    throw new CliParseError(`argument ${option}: invalid int value: '${raw}'`);
  }

  return BigInt(raw.replaceAll("_", ""));
}

function nextTokenLooksLikeOption(token) {
  if (token === undefined) {
    return true;
  }

  if (token.startsWith("--")) {
    return true;
  }

  if (token.startsWith("-") && !isPythonIntLiteral(token)) {
    return true;
  }

  return false;
}

export function parseArguments(argv, prog = programName()) {
  const values = new Map();
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      throw new CliHelpRequested();
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

      if (!LONG_OPTIONS.has(option)) {
        unknown.push(token);
        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const candidate = argv[index + 1];

        if (nextTokenLooksLikeOption(candidate)) {
          throw new CliParseError(`argument ${option}: expected one argument`);
        }

        rawValue = candidate;
        index += 1;
      }

      values.set(option.slice(2), parsePythonInt(option, rawValue));
      continue;
    }

    unknown.push(token);
  }

  if (unknown.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${unknown.join(" ")}`);
  }

  const missing = REQUIRED_OPTIONS
    .filter((name) => !values.has(name))
    .map((name) => `--${name}`);

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(", ")}`);
  }

  return {
    a: values.get("a"),
    b: values.get("b"),
    c: values.get("c"),
    d: values.get("d"),
    e: values.get("e"),
    prog,
  };
}

