import { Graph } from "./graph.mjs";
import { toNumber } from "./format.mjs";

class UnionFind {
  constructor(items) {
    this.parent = new Map();
    this.rank = new Map();

    for (const item of items) {
      this.parent.set(item, item);
      this.rank.set(item, 0);
    }
  }

  find(item) {
    const parent = this.parent.get(item);
    if (parent !== item) {
      this.parent.set(item, this.find(parent));
    }

    return this.parent.get(item);
  }

  union(left, right) {
    const leftRoot = this.find(left);
    const rightRoot = this.find(right);

    if (leftRoot === rightRoot) {
      return false;
    }

    const leftRank = this.rank.get(leftRoot);
    const rightRank = this.rank.get(rightRoot);

    if (leftRank < rightRank) {
      this.parent.set(leftRoot, rightRoot);
    } else if (leftRank > rightRank) {
      this.parent.set(rightRoot, leftRoot);
    } else {
      this.parent.set(rightRoot, leftRoot);
      this.rank.set(leftRoot, leftRank + 1);
    }

    return true;
  }
}

export function minimumSpanningTree(graph) {
  const mst = new Graph();
  const nodes = graph.nodes();
  mst.addNodesFrom(nodes);

  const edges = graph
    .edges()
    .filter((edge) => edge.u !== edge.v)
    .sort((left, right) => {
      const weightDelta = toNumber(left.weight) - toNumber(right.weight);
      if (weightDelta !== 0) {
        return weightDelta;
      }

      return left.order - right.order;
    });

  const unionFind = new UnionFind(nodes);

  for (const edge of edges) {
    if (unionFind.union(edge.u, edge.v)) {
      mst.addEdge(edge.u, edge.v, edge.weight);
    }
  }

  return mst;
}

